## Why This Is Asked
Tests ability to map C streaming callbacks to Go channels, memory ownership across CGO boundaries, and robust cancellation in concurrent workloads.

## Key Concepts
- CGO memory ownership across callback boundaries
- Bridging C callbacks to Go channels with safe copying
- Per-call cancellation and resource lifecycle management
- Concurrency isolation for multiple streams

## Code Example
```go
// Pseudo CGO binding sketch (Go)
package main
/*
#include <stdlib.h>
#include <stdint.h>
typedef void (*chunk_cb)(const uint8_t* chunk, size_t len, void* user);
void stream_process(const uint8_t* data, size_t len, chunk_cb cb, void* user);
*/
import "C"

func ProcessStream(in []byte) (<-chan []byte, func(), error) {
    ch := make(chan []byte)
    done := make(chan struct{})

    // C callback that copies chunks to Go channel
    cb := func(chunk *C.uint8_t, len C.size_t, user unsafe.Pointer) {
        goSlice := C.GoBytes(unsafe.Pointer(chunk), C.int(len))
        select {
        case ch <- goSlice:
        case <-done:
        }
    }

    // Start processing and return cancellation
    go func() {
        C.stream_process((*C.uint8_t)(&in[0]), C.size_t(len(in)), 
                        (*C.chunk_cb)(unsafe.Pointer(&cb)), nil)
        close(ch)
    }()

    cancel := func() { close(done); /* free C resources */ }
    return ch, cancel, nil
}
```

## Why This Is Asked
Tests memory ownership across the CGO boundary and safe deallocation. Tokenization is simple in C but memory mgmt is error-prone; the Go binding must copy results and free C memory in all paths, including errors. Running two tokenizations concurrently checks thread safety of the wrapper.

## Key Concepts
- CGO memory ownership and malloc/free
- Converting C arrays of strings to Go slices
- Error propagation and nil checks
- Concurrency safety with CGO calls

## Code Example
```c
// header (tokenize.h)
char** tokenize(const char* input, size_t* count);
```

```c
// minimal implementation (tokenize.c)
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

char** tokenize(const char* input, size_t* count) {
  if (!input) { *count = 0; return NULL; }
  // simple two-pass: count tokens
  size_t n = 0; const char* p = input; while (*p) { while (isspace((unsigned char)*p)) p++; if (*p) { n++; while (*p && !isspace((unsigned char)*p)) p++; } }
  char** tokens = (char**)malloc(n * sizeof(char*));
  if (!tokens) { *count = 0; return NULL; }
  size_t idx = 0; p = input; while (*p) {
    while (*p && isspace((unsigned char)*p)) p++;
    if (!*p) break;
    const char* start = p; while (*p && !isspace((unsigned char)*p)) p++;
    size_t len = p - start;
    tokens[idx] = (char*)malloc(len + 1);
    memcpy(tokens[idx], start, len);
    tokens[idx][len] = '\0';
    idx++;
  }
  *count = idx;
  return tokens;
}
```

```go
// Go binding sketch (tokenize.go)
package main

/*
#include <stdlib.h>
#include "tokenize.h"
*/
import "C"
import (
  "errors"
  "unsafe"
)

func Tokenize(text string) ([]string, error) {
  cstr := C.CString(text)
  defer C.free(unsafe.Pointer(cstr))
  var count C.size_t
  tokens := C.tokenize(cstr, &count)
  if tokens == nil {
    return nil, errors.New("tokenize failed")
  }
  // copy to Go and free C memory
  result := make([]string, int(count))
  for i := 0; i < int(count); i++ {
    s := C.GoString(tokens[i])
    result[i] = s
    C.free(unsafe.Pointer(tokens[i]))
  }
  C.free(unsafe.Pointer(tokens))
  return result, nil
}
```

```go
// concurrent usage (main.go)
package main
import (
  "fmt"
  "sync"
)

func main() {
  var wg sync.WaitGroup
  inputs := []string{"hello world from CGO", "Go + C interop"}
  for _, s := range inputs {
    wg.Add(1)
    go func(text string) {
      defer wg.Done()
      out, err := Tokenize(text)
      if err != nil { fmt.Println("err:", err); return }
      fmt.Println(out)
